private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and vertices cannot be null or empty");
    }

    int n = vertices.size();
    if (n <= 1) {
        return true; // A graph with 0 or 1 vertex is always a clique
    }

    for (V v : vertices) {
        Set<E> neighbors = graph.neighbors(v);
        if (neighbors.size() < n - 1) {
            return false; // A vertex must have at least n-1 neighbors to form a clique
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list cannot be null or empty");
    }

    List<Integer> lowerBounds = new ArrayList<>();
    int currentLowerBound = Integer.MAX_VALUE;

    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        int lowerBound = key.compareTo(currentLowerBound);
        if (lowerBound < 0) {
            currentLowerBound = lowerBound;
        }
        lowerBounds.add(currentLowerBound);
    }

    return lowerBounds;
}

private void pop(final String descriptor) {
    // Check if the descriptor is valid
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // Split the descriptor into its components
    String[] components = descriptor.split(" ");
    if (components.length == 0) {
        throw new IllegalArgumentException("Invalid descriptor format");
    }

    // Determine the type of the descriptor
    String type = components[0];
    if (!type.equals("abstract")) {
        throw new IllegalArgumentException("Descriptor must start with 'abstract'");
    }

    // Determine the number of arguments
    int numArgs = 0;
    for (int i = 1; i < components.length; i++) {
        if (components[i].equals("type")) {
            numArgs++;
        }
    }

    // Pop the abstract types from the output frame stack
    for (int i = 0; i < numArgs; i++) {
        // Assuming the output frame stack is a stack of objects
        Object obj = outputFrameStack.pop();
        if (obj == null) {
            throw new IllegalStateException("Output frame stack is empty");
        }
    }
}

