private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list cannot be null or empty");
    }

    List<Integer> upperBounds = new ArrayList<>();
    int minKey = Integer.MAX_VALUE;

    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        if (key.compareTo(minKey) < 0) {
            minKey = key;
        }
    }

    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        upperBounds.add(minKey);
    }

    return upperBounds;
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    StringBuilder encoded = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            encoded.append("%");
            encoded.append(c);
        } else {
            encoded.append(c);
        }
    }
    return encoded.toString();
}

public static boolean equals(Point2D p1, Point2D p2) {
    if (p1 == null || p2 == null) {
        throw new IllegalArgumentException("Both points must be non-null");
    }
    return Math.abs(p1.getX() - p2.getX()) < 1e-9 && Math.abs(p1.getY() - p2.getY()) < 1e-9;
}

